    IEnumerator AIRun(){
        app.ScriptedInputs=null;app.LocalDevice=0;app.AuditKeyState=k=>false;app.AuditMousePosition=new Vector3(-1,-1,0);
        for(int arena=0;arena<3;arena++){
            app.BeginMatch(arena,0);yield return Wait(3.3f);var b=app.Wrestlers[1];int observed=0,rebuilds=0;float travel=0;var previous=b.Root.position;float end=Time.realtimeSinceStartup+8;bool intact=true;
            while(Time.realtimeSinceStartup<end){
                // An autonomous ring-out legitimately rebuilds the world for
                // the next round. Always measure its current wrestler; retaining
                // the previous round's Rigidbody across a yield dereferences a
                // destroyed Unity object. Spawn/reset jumps are not locomotion.
                var current=app.Wrestlers[1];
                if(current!=b){b=current;previous=b.Root.position;rebuilds++;}
                observed|=b.command.flags;Vector3 position=b.Root.position;travel+=Vector3.Distance(previous,position);previous=position;
                intact&=Finite()&&b.JointSeparation()<.06f;
                yield return null;
            }
            Check("ai_autonomous_arena_"+arena,observed!=0&&travel>.5f,"commands="+observed+" physical travel="+travel+" round rebuilds="+rebuilds);Check("ai_connected_finite_"+arena,intact&&Finite()&&app.Wrestlers[1].JointSeparation()<.06f,"real physical opponent monitored across round transitions; no test input array");Check("ai_full_view_arena_"+arena,!app.Views.Split&&app.Views.PrimaryPlayer==0&&Camera.allCamerasCount==1,"one controlled-player camera");app.Capture(Path.Combine(directory,"ai-arena-"+arena+".png"));
        }
        app.BeginMatch(0,0);yield return Wait(.5f);var safe=GBBot.SafeMove(app,new Vector3(2.6f,1.2f,-3.5f),Vector3.right);Check("ai_rejects_unguarded_edge",safe.x<.5f,"unsafe rightward deck edge redirected or stopped: "+safe);
        app.BeginMatch(3,1);yield return Wait(3.3f);int pinCommands=0,pinActiveFrames=0;float pinMove=0,pinEnd=Time.realtimeSinceStartup+4;bool pinModeActive=true;
        while(Time.realtimeSinceStartup<pinEnd){
            // A decision can deliberately release every action for an opening
            // or cooldown. Observe the exchange, not one arbitrary final frame.
            var decision=app.Wrestlers[1].command;pinCommands|=decision.flags;pinMove=Mathf.Max(pinMove,decision.Move.magnitude);
            if(decision.flags!=0||decision.Move.sqrMagnitude>.01f)pinActiveFrames++;
            pinModeActive&=app.LocalAI&&app.CurrentMode==1;yield return null;
        }
        Check("ai_pin_rules_available",pinModeActive&&pinCommands!=0&&pinActiveFrames>0,"AI pin match activity across 4 seconds; commands="+pinCommands+" max move="+pinMove.ToString("0.00")+" active frames="+pinActiveFrames);
        app.BeginMatch(3,1);yield return Wait(3.3f);var attacker=app.Wrestlers[1];var defender=app.Wrestlers[0];attacker.ResetTo(new Vector3(-.7f,.25f,0));defender.ResetTo(Vector3.zero);Quaternion flat=Quaternion.Euler(-90,0,0);
        for(int n=0;n<15;n++){defender.bodies[n].position=new Vector3(.35f,.43f,0)+flat*(defender.initial[n]-defender.initial[1]);defender.bodies[n].rotation=flat;defender.bodies[n].linearVelocity=Vector3.zero;defender.bodies[n].angularVelocity=Vector3.zero;}defender.downUntil=Time.time+6;defender.recoveryUntil=Time.time+7;
        yield return Wait(4.8f);Check("ai_completes_physical_pin",app.Scores[1]==1,"AI selected grips and pin without supplied commands; score="+app.Scores[1]);app.Capture(Path.Combine(directory,"ai-pin.png"));
        app.BeginMatch(3,2);yield return Wait(.3f);Check("training_no_ai_attacks",!app.LocalAI&&app.Wrestlers[1].command.flags==0,"passive partner and separate dummy");
        app.Network.role=GBNetwork.Role.Host;Check("online_never_uses_local_ai",!app.LocalAI,"remote human retains authority input");app.Network.role=GBNetwork.Role.Offline;
        app.AuditKeyState=null;app.AuditMousePosition=null;app.ReturnToMenu();Check("ai_no_runtime_issues",app.Issues.Count==0,string.Join("; ",app.Issues));
    }
    void CloseSetup(){var a=app.Wrestlers[0];var b=app.Wrestlers[1];a.ResetTo(new Vector3(-.5f,.25f,0));b.ResetTo(new Vector3(.5f,.25f,0));app.ScriptedInputs[0]=new GBInput{ax=1,az=0};app.ScriptedInputs[1]=new GBInput{ax=-1,az=0};}
    IEnumerator Functional() {
        app.BeginMatch(3,2);Neutral();yield return Wait(4);
