        var center=(a.Root.position+b.Root.position)*.5f;for(int view=0;view<3;view++){Vector3 offset=view==0?new Vector3(3,2,-4):view==1?new Vector3(-4,1.5f,0):new Vector3(0,2,4);app.CaptureAt(Path.Combine(directory,"body-connection-"+view+".png"),center+offset,center+Vector3.up*.25f);}
        Check("physical_lift",b.Root.position.y>before+.15f,"opponent y before="+before.ToString("0.00")+" after="+b.Root.position.y.ToString("0.00")+" lifter="+a.Root.position.y.ToString("0.00")+" grips="+a.GripCount+" stamina="+a.stamina.ToString("0.0"));
        float bx=b.Root.position.x;app.ScriptedInputs[0]=new GBInput{ax=1,flags=GBInput.Left|GBInput.Right|GBInput.Throw};yield return Wait(.3f);Check("throw_release",a.GripCount==0,"hands after throw="+a.GripCount);yield return Wait(.7f);Check("throw_displacement",b.Root.position.x>bx+.4f,"displacement="+(b.Root.position.x-bx).ToString("0.00"));
        Neutral();yield return Wait(2);CloseSetup();yield return Wait(.7f);app.ScriptedInputs[0]=new GBInput{ax=1,flags=GBInput.Left|GBInput.Right};yield return Wait(2);float stamina=a.stamina;app.ScriptedInputs[1]=new GBInput{ax=-1,flags=GBInput.Brace};yield return Wait(1.2f);Check("escape_cost",a.stamina<stamina,"attacker stamina="+stamina.ToString("0.0")+" â†’ "+a.stamina.ToString("0.0"));
        Neutral();yield return Wait(.5f);Check("release_cleanup",a.GripCount==0&&a.hands[0].target==null&&a.hands[1].target==null,"all hand constraints released");
        a.ResetTo(new Vector3(0,.25f,0));Neutral();yield return Wait(.6f);a.Knock(100,.7f);yield return Wait(.1f);Check("knockdown",a.Down,"damage transitioned to reduced muscle state");yield return Wait(3.5f);Check("knockdown_recovery",!a.Down&&a.Root.position.y>.95f,"pelvis y="+a.Root.position.y.ToString("0.00"));app.Capture(Path.Combine(directory,"recovery.png"));
        int count=app.Registry.Count;app.ResetRound(false);yield return Wait(.5f);Check("reset_registry",app.Registry.Count==count,"objects="+count+" after="+app.Registry.Count);
        for(int arena=0;arena<3;arena++){app.BeginMatch(arena,0);Neutral();yield return Wait(4);Check("arena_"+arena,app.Wrestlers.Count==2&&app.Registry.Count>30,"objects="+app.Registry.Count);app.Capture(Path.Combine(directory,"arena-"+arena+".png"));}
        app.BeginMatch(1,0);Neutral();yield return Wait(3.3f);app.Wrestlers[0].ResetTo(new Vector3(11,0,0));yield return Wait(.6f);Check("round_scoring",app.Scores[1]==1,"score="+app.Scores[0]+":"+app.Scores[1]);
        app.ResetRound(false);yield return Wait(.3f);app.Wrestlers[0].ResetTo(new Vector3(-11,0,0));app.Wrestlers[1].ResetTo(new Vector3(11,0,0));yield return Wait(.6f);Check("simultaneous_draw",app.Scores[0]==0&&app.Scores[1]==1,"message="+app.RoundMessage);
