        Check("finite_body_states",Finite(),"all positions finite");Check("no_runtime_issue",app.Issues.Count==0,string.Join("; ",app.Issues));
    }
    IEnumerator Record(){
        app.BeginMatch(3,1);Neutral();yield return Wait(3.5f);CloseSetup();yield return Wait(1);int frame=0;float seconds=float.Parse(Arg("--seconds","18"));float end=Time.realtimeSinceStartup+seconds,next=Time.realtimeSinceStartup;
        while(Time.realtimeSinceStartup<end){float t=Time.realtimeSinceStartup-started;for(int i=0;i<2;i++){var w=app.Wrestlers[i];var rival=app.Wrestlers[1-i];var d=(rival.Root.position-w.Root.position).normalized;int bits=GBInput.Left|GBInput.Right|GBInput.HandAim;if(t%8>3)bits|=GBInput.Lift;if(t%8>5.2f&&t%8<5.7f)bits&=~3;if(rival.Down)bits|=GBInput.Pin;if(w.IsBeingPinned)bits|=GBInput.Brace;Vector3 hand=Vector3.ClampMagnitude(rival.bodies[1].position-w.Root.position+Vector3.up*Mathf.Sin(t*1.5f)*.3f,1.25f);app.ScriptedInputs[i]=new GBInput{x=d.x*.25f,z=d.z*.25f,ax=d.x,az=d.z,hx=hand.x,hy=hand.y,hz=hand.z,flags=bits};}if(Time.realtimeSinceStartup>=next){app.Capture(Path.Combine(directory,"frame-"+(frame++).ToString("D4")+".png"));next+=.1f;}yield return null;}
        Check("gameplay_frames",frame>100,"recorded="+frame+" at 10 fps; current arm/cover controls");
    }
    IEnumerator Moves(){
