        app.BeginMatch(2,0);Neutral();yield return Wait(3.2f);app.Arena.elapsed=70;yield return Wait(.2f);Check("collapse_warning_before_failure",app.Arena.WarningSection==0&&!app.Arena.towerSections[0].broken,"warning precedes collapse by six seconds");app.Arena.elapsed=76;yield return Wait(.2f);Check("platform_failure",app.Arena.towerSections[0].broken,"platform pieces dynamic");
        app.BeginMatch(0,2);Neutral();yield return Wait(1);app.BeginMatch(0,0);Neutral();yield return Wait(3.2f);a=app.Wrestlers[0];app.ScriptedInputs[0]=new GBInput{az=1,flags=GBInput.Brace};yield return Wait(2);float headTop=a.bodies[2].position.y+.19f;Check("duck_clearance",headTop<1.415f,"head top="+headTop.ToString("0.00")+" beam bottom=1.415");app.CaptureAt(Path.Combine(directory,"duck.png"),a.Root.position+new Vector3(4,2,-4),a.Root.position+Vector3.up*.5f);
        app.BeginMatch(3,1);Neutral();yield return Wait(3.2f);a=app.Wrestlers[0];b=app.Wrestlers[1];a.ResetTo(new Vector3(-.7f,.25f,0));b.ResetTo(Vector3.zero);Quaternion flat=Quaternion.Euler(-90,0,0);for(int n=0;n<15;n++){b.bodies[n].position=new Vector3(.35f,.43f,0)+flat*(b.initial[n]-b.initial[1]);b.bodies[n].rotation=flat;b.bodies[n].linearVelocity=Vector3.zero;b.bodies[n].angularVelocity=Vector3.zero;}b.downUntil=Time.time+6;b.recoveryUntil=Time.time+7;app.ScriptedInputs[0]=new GBInput{ax=1,flags=3|GBInput.Pin};yield return Wait(4);Check("physical_three_count",app.Scores[0]==1,"score="+app.Scores[0]+" pin="+app.PinCount.ToString("0.00")+" grip="+a.GripCount+" shoulder="+b.bodies[1].position.y.ToString("0.00"));app.CaptureAt(Path.Combine(directory,"pin.png"),new Vector3(4,3,-5),Vector3.up*.8f);
        Check("runtime_no_issues",app.Issues.Count==0,string.Join("; ",app.Issues));
