    IEnumerator NetworkRun() {
        int p=int.Parse(Arg("--port","27844"));app.Network.latencySimulation=int.Parse(Arg("--delay","0"));app.Network.dropSimulation=float.Parse(Arg("--drop","0"),System.Globalization.CultureInfo.InvariantCulture);app.SelectedArena=3;app.SelectedMode=1; // only pin rules and arm targets
        bool tunnel=Has("--tunnel"),host=Has("--host-test");
        if(host){app.PlayerName="HOST";if(tunnel){app.Network.HostInvite();app.ShowMenu("online");float linkDeadline=Time.realtimeSinceStartup+120;while(!app.Network.InviteReady&&Time.realtimeSinceStartup<linkDeadline&&app.Network.role!=GBNetwork.Role.Offline)yield return null;Check("tunnel_invite_ready",app.Network.InviteReady,app.Network.status);if(!app.Network.InviteReady)yield break;bool copied=app.CopyInvite();Check("copy_invite_clipboard",copied&&GUIUtility.systemCopyBuffer==app.Network.InviteLink,"Copy Invite uses full link including room token");File.WriteAllText(Path.Combine(directory,"invite.txt"),GUIUtility.systemCopyBuffer);ScreenCapture.CaptureScreenshot(Path.Combine(directory,"host-invite.png"));yield return Wait(.4f);}else app.Network.Host(p,"audit-room-7365");}
        else {app.PlayerName="CLIENT";if(tunnel){string linkFile=Path.Combine(directory,"invite.txt");float linkDeadline=Time.realtimeSinceStartup+130;while(!File.Exists(linkFile)&&Time.realtimeSinceStartup<linkDeadline)yield return null;if(!File.Exists(linkFile)){Check("tunnel_invite_received",false,"Host did not produce invite");yield break;}string link=File.ReadAllText(linkFile);Check("paste_invite_valid",GBNetwork.ValidateInvite(link),"full public invite accepted");Check("reject_fake_invite",!GBNetwork.ValidateInvite("https://example.com/room#grip=abcdefgh"),"unrelated hosts rejected");if(!app.Network.JoinInvite(link)){Check("tunnel_join_started",false,app.Network.status);yield break;}}else app.Network.Join(Arg("--address","127.0.0.1"),p,"audit-room-7365");}
        float deadline=Time.realtimeSinceStartup+(tunnel?120:25);while(!app.Network.connected&&Time.realtimeSinceStartup<deadline)yield return null;
        Check("network_handshake",app.Network.connected,app.Network.status);if(!app.Network.connected)yield break;
        app.Network.SetReady(true);app.Network.Lobby();deadline=Time.realtimeSinceStartup+10;
        if(Has("--host-test")){while(!app.Network.peerReady&&Time.realtimeSinceStartup<deadline)yield return null;Check("both_ready",app.Network.peerReady,"private ready-state synchronization");app.Network.StartMatch();}
        while(!app.InMatch&&Time.realtimeSinceStartup<deadline)yield return null;
        yield return Wait(.15f);Check("connected_camera_owner",!app.Views.Split&&app.Views.PrimaryPlayer==(Has("--host-test")?0:1),"connected peer owns its wrestler camera");CameraCheck("connected_wrestler_centered");if(!Application.isBatchMode)ScreenCapture.CaptureScreenshot(Path.Combine(directory,Has("--host-test")?"host-follow.png":"client-follow.png"));
        float end=Time.realtimeSinceStartup+float.Parse(Arg("--seconds","35")),matchStart=Time.realtimeSinceStartup;bool didRingOut=false,sawRingCountdown=false,sawRingBottom=false;int ringCounts=0;bool sawBroken=false,didBreak=false,didReset=false,sawHandInput=false,sawSprawlInput=false;int maxTargets=0,firstEpoch=app.Epoch,lastEpoch=app.Epoch;while(Time.realtimeSinceStartup<end&&app.Network.connected){float t=Time.realtimeSinceStartup-started;for(int i=0;i<2;i++){var other=app.Wrestlers[1-i].Root.position-app.Wrestlers[i].Root.position;var move=other.normalized;int bits=GBInput.Left|GBInput.Right;if(t%7>3)bits|=GBInput.Lift;bits|=GBInput.HandAim;if(t%7<.8f)bits=GBInput.Sprawl|GBInput.HandAim;if(t%7>5.4f&&t%7<5.9f)bits&=~3;Vector3 hand=Vector3.ClampMagnitude(other+Vector3.up*.45f,1.2f);app.ScriptedInputs[i]=new GBInput{x=move.x*.4f,z=move.z*.4f,ax=move.x,az=move.z,hx=hand.x,hy=hand.y,hz=hand.z,flags=bits};}if(host)sawHandInput|=app.Network.remoteInput.HasHandAim&&app.Network.remoteInput.HandOffset.sqrMagnitude>.1f&&!app.Network.remoteInput.Has(GBInput.Throw);if(host)sawSprawlInput|=app.Network.remoteInput.Has(GBInput.Sprawl);int targets=0;foreach(var w in app.Wrestlers)foreach(var hand in w.hands)if(hand.target)targets++;maxTargets=Mathf.Max(maxTargets,targets);foreach(var prop in app.Arena.breakables)if(prop.broken)sawBroken=true;lastEpoch=app.Epoch;if(app.RingRestartCountdown){sawRingCountdown=true;ringCounts|=1<<app.CountdownNumber;sawRingBottom|=app.Wrestlers[1].Root.position.y<.85f&&app.Wrestlers[0].Root.position.z<app.Wrestlers[1].Root.position.z-.45f&&app.Wrestlers[0].Root.position.y<.95f;}if(host&&Has("--ringout-network")&&!didRingOut&&Time.realtimeSinceStartup-matchStart>8){app.Wrestlers[1].ResetTo(new Vector3(5.5f,1,0));app.CheckRingOut();didRingOut=true;}if(Has("--host-test")){if(!didBreak&&Time.realtimeSinceStartup-matchStart>5){app.Arena.breakables[0].Break();didBreak=true;}if(!didReset&&Time.realtimeSinceStartup-matchStart>15){app.ResetRound(false);di