        if(Has("--ringout-network")){Check("ringout_countdown_stream",sawRingCountdown&&ringCounts==14,"observed 3/2/1 mask="+ringCounts);Check("ringout_bottom_pose_stream",sawRingBottom,"client wrestler low, host wrestler behind; same protocol12 snapshot");}
        Check("pin_only_network_world",app.CurrentMode==1&&app.CurrentArena==3,"both peers run ring pins");if(host)Check("remote_3d_arm_targets",sawHandInput,"protocol9 passes bounded arm/sprawl input; no retired Throw bit");if(host)Check("remote_sprawl_input",sawSprawlInput,"protocol9 preserves dedicated sprawl through authenticated peer input");Check("physical_grip_state_stream",maxTargets>0,"maximum simultaneous hand targets="+maxTargets);Check("prop_break_stream",sawBroken,"observed broken prop state");Check("round_reset_stream",lastEpoch>firstEpoch,"epoch="+firstEpoch+" â†’ "+lastEpoch);
        if(Has("--host-test"))Check("network_survival",app.Network.connected,app.Network.status);else Check("host_disconnect_returns_to_menu",!app.Network.connected&&!app.InMatch,app.Network.status);Check("state_stream",Has("--host-test")?app.Network.snapshotsSent>50:app.Network.snapshotsReceived>50,"sent="+app.Network.snapshotsSent+" received="+app.Network.snapshotsReceived);
