    }
    IEnumerator Soak(){app.BeginMatch(0,0);Neutral();float seconds=float.Parse(Arg("--seconds","1200"));float end=Time.realtimeSinceStartup+seconds,nextArena=Time.realtimeSinceStartup+180,nextLog=Time.realtimeSinceStartup+60;int rounds=1,visited=1;while(Time.realtimeSinceStartup<end){if(app.Phase==GBApp.GamePhase.MatchOver||Time.realtimeSinceStartup>nextArena){int arena=(rounds++)%3;visited|=1<<arena;app.BeginMatch(arena,0);nextArena=Time.realtimeSinceStartup+180;}for(int i=0;i<2;i++){float t=Time.realtimeSinceStartup;var d=(app.Wrestlers[1-i].Root.position-app.Wrestlers[i].Root.position).normalized;int bits=3;if(t%9>4)bits|=16;if(t%9>6&&t%9<6.15f)bits|=32;if(t%9>6.2f&&t%9<6.8f)bits&=~3;if(t%13>10)bits|=128;app.ScriptedInputs[i]=new GBInput{x=d.x*.55f,z=d.z*.55f,ax=d.x,az=d.z,flags=bits};}if(!Finite()){Check("soak_finite",false,"invalid position");break;}if(Time.realtimeSinceStartup>nextLog){string progress="seconds="+(Time.realtimeSinceStartup-started).ToString("0")+" arena="+app.CurrentArena+" epoch="+app.Epoch+" fps="+app.MeasuredFPS.ToString("0.0")+" gap="+maximumJointGap.ToString("0.0000")+" issues="+app.Issues.Count;File.WriteAllText(Path.Combine(directory,"progress.txt"),progress);Debug.Log("GRIP_SOAK "+progress);nextLog+=60;}yield return null;}Check("continuous_duration",Time.realtimeSinceStartup-started>=seconds,"seconds="+(Time.realtimeSinceStartup-started).ToString("0.0"));Check("all_competitive_arenas",visited==7,"visited mask="+visited);Check("soak_finite",Finite(),"all position and rotation components finite");Check("soak_no_issues",app.Issues.Count==0,string.Join("; ",app.Issues));app.Capture(Path.Combine(directory,"soak.png"));}
    bool Valid(float v){return !float.IsNaN(v)&&!float.IsInfinity(v);}
    bool Finite(){foreach(var b in app.Registry){var p=b.position;var q=b.rotation;if(!Valid(p.x)||!Valid(p.y)||!Valid(p.z)||!Valid(q.x)||!Valid(q.y)||!Valid(q.z)||!Valid(q.w))return false;}return true;}
    void Finish(string file){if(app.Authority){Check("connected_body_joints",missingJointFrames==0&&maximumJointGap<.06f,"missing frames="+missingJointFrames+" maximum physical anchor separation="+maximumJointGap.ToString("0.0000")+" m");}report.duration=Time.realtimeSinceStartup-started;report.averageFps=app.MeasuredFPS;report.minFps=app.MinFPS;report.bodies=app.Registry.Count;report.issues=app.Issues.Count;report.screenWidth=Screen.width;report.screenHeight=Screen.height;File.WriteAllText(Path.Combine(directory,file),JsonUtility.ToJson(report,true));Debug.Log("GRIP_AUDIT_FINISHED "+file);Application.Quit();}
